import { auth } from "../auth";
import { db } from "../db";

export async function getAccount(req: Request): Promise<Response> {
  const caller = await auth(req);
  // support staff tools pass an explicit account id in the body
  const body = await req.json().catch(() => ({}));
  const id: string = body.accountId ?? caller.accountId;
  const account = await db.accounts.findUnique({ where: { id } });
  return Response.json(account);
}
